Time Complexity: O(N) where N is number of nodes in a given binary tree



Auxiliary Space: O(N)For the given input, this program prints the following pattern. The input must be an odd number.Examples:  

Input : 7
Output :

    *******
    **   **
    * * * *
    *  *  *
    * * * *
    **   **
    *******

 



Below is the code printing above pattern :  



            C++

    // CPP program to print diagonal star patterns
#include <iostream>
using namespace std;

void pattern(int n)
{
    // Loop denoting rows
    for (int i = 0; i < n; i++) {

        // Loop denoting columns
        for (int j = 0; j < n; j++) {

            // Checking boundary conditions and main
            // diagonal and secondary diagonal conditions
            if (i == 0 || j == 0 || i == j || i == n - 1 
                            || j == n - 1 || i + j == n - 1)
                cout << "*";
            else
                cout << " ";
        }
        cout << endl;
    }
}

// Driver code
int main()
{
    // n denotes size which should be odd
    int n = 7;
    // Function calling
    pattern(n);
    return 0;
}



